// src/components/SubjectCard.jsx
import React from "react";

const SubjectCard = ({ name, icon, iat, iatTotal, lab, labTotal, assignments, assignmentsTotal }) => (
  <div className="subject-card">
    <div className="subject-card-header">
      <div className="subject-icon">
        <i className={`fa-solid ${icon}`}></i>
      </div>
      <div className="subject-title">{name}</div>
    </div>
    <div className="subject-card-body">
      <div>IAT Marks: <b>{iat} / {iatTotal}</b></div>
      <div>Lab Marks: <b>{lab} / {labTotal}</b></div>
      <div>Assignments: <b>{assignments} / {assignmentsTotal}</b></div>
    </div>
  </div>
);

export default SubjectCard;
